 let L=V06_LAYER_DATA[v06Run.layer];if(!L)return;v06Run.spawnT-=dt;if(v06Run.spawnT<=0){v06Run.spawnT=L.spawn;v06SpawnMob();if(v06Run.layer>=4&&Math.random()<.28)v06SpawnMob()}
