    v065SpawnWave(c,{x,y,a:d.a,speed:380*speedMul,span:220*area,thick:115*area,duration:1.15*(1+m.duration),pull:285,push:335,damage:calc(c,{atk:.18,cold:.50}),chill:2,color:'#75d8ff'});return;
