    b.onclick=()=>{c.ep=clamp(c.ep+amount*(v107Has(c,'impmonGun')?1.5:1),0,999);effects.push({type:'reactionText',text:`EVO +${amount}`,x:c.x,y:c.y-48,t:.9,total:.9,color:'#78b7ff'});closeModal()};
