 u.t+=dt;$('#ultName').style.opacity=u.t<.75?'1':'0';
 if(!u.done&&u.t>=.58){u.done=true;v092CastQ(u);flash('white',65);slowMoT=Math.max(slowMoT,.07)}
 if(u.t>=u.duration)v080FinishUlt(u.c);
