 const single=['woodmon','cherrymon','pinocchimon','diatrymon','dinorexmon'].includes(c.form),target=single?v10TargetUnderCursor(c,{woodmon:540,cherrymon:600,pinocchimon:650,diatrymon:750,dinorexmon:950}[c.form]):null;
