 vXpMotes.length=0;vXpAbsorbed=0;VXP_initGameBase();
 document.title='디지몬 서바이버 · 경험치 흡수 테스트';
 const badge=$('#buildBadge');if(badge)badge.textContent='EXP DUST TEST';
