function v108GiantSplash(points){
 if(points<=0)return null;
 return points<10?{radius:38+4*points,ratio:.10+.025*points}
                 :{radius:100+4*(points-10),ratio:.50+.02*(points-10)};
}
const V108B_projectileHit=v10ProjectileHit;
