 if(p.type==='circle'){p.r*=2;for(const q of effects)if(q.type==='warningCircleGrow'&&Math.abs(q.t-p.t)<.04&&Math.hypot(q.x-p.tx,q.y-p.ty)<2)q.r=p.r}
