 const t=cin.t,x=W/2,y=H/2,fade=Math.min(.73,Math.sin(Math.PI*t/cin.duration)*.73);
 ctx.save();ctx.fillStyle=`rgba(3,7,20,${fade})`;ctx.fillRect(0,0,W,H);
