   const c=activeChar();if(!c)break;
   const mark={x:c.x,y:c.y,r:180,at:p.elapsed+.78,done:false};p.marks.push(mark);
   effects.push({type:'warningCircleGrow',x:mark.x,y:mark.y,r:mark.r,t:.78,total:.78,color:'#ff596a'});p.next++
