const V014_ELEMENT_NAMES={physical:'물리',fire:'화염',cold:'냉기',nature:'자연',electric:'전기',wind:'바람',earth:'땅',light:'빛',dark:'어둠'};
const v014Unique=a=>[...new Set(a.filter(Boolean))];
for(const [form,attrs] of Object.entries(V014_NATIVE))V109_IDENTITIES[form]=[...attrs];
v013LineageIdentity=function(form){return [...(V014_NATIVE[form]||V109_IDENTITIES[form]||V012_SKILL_ELEMENTS[form]||[])]};
