const V014_evolve=evolve;
evolve=function(c,form){const before=c?.form,attrs=c?[...v013Attrs(c)]:[];const result=V014_evolve(c,form);if(c&&before!==c.form){c.v014Attrs=v014Unique([...attrs,...v013LineageIdentity(c.form)]);(c.v014History??=[before]).push(c.form)}return result};
const V014_applyStatus=applyStatus;
applyStatus=function(e,element,stacks,source){const before=e?.breakStacks||0,frozen=(e?.freezeT||0)>0;v109BypassIdentity++;let result;try{result=V014_applyStatus(e,element,stacks,source)}finally{v109BypassIdentity--}
 if(element==='physical'&&stacks>0&&!frozen&&before+stacks>=5&&e&&!e.dead&&e.v111GaugeMax&&e.v111Groggy<=0&&e.v111Grace<=0){e.v111Gauge=Math.min(e.v111GaugeMax,e.v111Gauge+75);if(e.v111Gauge>=e.v111GaugeMax){e.v111Gauge=0;e.v111Groggy=5;e.v111ReactionBonus=0;effects.push({type:'ring',x:e.x,y:e.y,r:(e.r||30)+28,t:.4,color:'#ffe77f'})}}return result};
const V014_skillInfo=skillInfo;
skillInfo=function(c){const lines=V014_skillInfo(c)||[];if(!c)return lines;const description=c.form==='mitamamon'?'속성: ??? · 전 속성':'속성: '+v013Attrs(c).map(x=>V014_ELEMENT_NAMES[x]).join(' + ');return [...lines.filter(x=>!x.startsWith('속성:')),description]};
