const V014_removeRelic=v107RemoveRelic;
v107RemoveRelic=function(c,i){const r=v107Relics(c)[i];if(!r)return;const result=V014_removeRelic(c,i);if(r.id==='dashcrit'){c.v109DashBreaker=false;c.v109DashT=0}if(r.id==='tagpower')c.mods.tagPower=false;if(r.id==='ultreset')c.mods.ultResetE=false;c.uniqueSet?.delete(r.id);return result};
