function v014ShopLayout(active){const box=$('#choices'),layout=document.getElementById('v014ShopLayout');if(active){if(layout)return layout;const panel=document.createElement('div');panel.id='v014ShopLayout';box.parentElement.insertBefore(panel,box);panel.appendChild(box);const sale=document.createElement('div');sale.id='v014SellPanel';panel.appendChild(sale);return panel}if(layout){layout.parentElement.insertBefore(box,layout);layout.remove()}return null}
const V014_modal=v107Modal;
