// v.0.14.c: apply charge efficiency to an uncapped event gain. All hit and kill
// wrappers inside this transaction see a temporary zero meter, so their early
// clamp(…, 100) cannot discard the part needed to finish the last percentage.
function v014cChargeEvent(source,run){
 if(!source||source.v014cChargeBusy||!Number.isFinite(source.ult))return run();
 const before=clamp(source.ult,0,100),penalty=source.v107UltChargePenalty||0;
 source.v014cChargeBusy=true;
 source.ult=0;
 try{return run()}
 finally{
  const raw=Math.max(0,source.ult);
  source.ult=clamp(before+raw/(1+Math.max(0,penalty)),0,100);
  source.v014cChargeBusy=false
 }
}
const V014C_hitEnemy=hitEnemy;
hitEnemy=function(e,amount,source,...args){return v014cChargeEvent(source,()=>V014C_hitEnemy(e,amount,source,...args))};
const V014C_killEnemy=killEnemy;
killEnemy=function(e,source){return v014cChargeEvent(source,()=>V014C_killEnemy(e,source))};
const V014C_initGame=initGame;
initGame=function(){const result=V014C_initGame();document.title='디지몬 RE:서바이버 v.0.14.c';const badge=$('#buildBadge');if(badge)badge.textContent='BUILD v.0.14.c';return result};
